        Grade::Identified => (Some(Verdict::Pass), ReportState::Pass),
        Grade::NotIdentified => (Some(Verdict::CalibrationRegion), ReportState::ManualCheck),
        Grade::NoRankedHypotheses | Grade::NoAttributableIncident | Grade::ReadBackFailed => {
