}

/// `conductor` with neither neighbour in `[a-z0-9_-]`.
fn names_conductor(lower: &str) -> bool {
    let bytes = lower.as_bytes();
    let joins = |b: u8| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_' || b == b'-';
