fn route(capture: &str) -> Route {
    if capture.lines().any(|l| l == NO_EMISSION) {
        return Route::PreflightBlocked;
    }
    match trace_field(capture, "retrieve_report_witness") {
        Some("true") => Route::ReadBack,
        _ => Route::EmittedNoReadBack,
    }
}

